const express = require('express');
const { EventStoreDBClient, jsonEvent } = require('@eventstore/db-client');
const { jwtAuth } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const esClient = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.post('/api/commands/locks/:lockId/disarm', jwtAuth, async (req, res) => {
  const { lockId } = req.params;
  const { reason } = req.body;

  const access = await db.query(
    'SELECT id FROM household_lock_permissions WHERE lock_id = $1 AND user_id = $2',
    [lockId, req.user.id]
  );
  if (!access.rows.length) {
    return res.status(403).json({ error: 'Access denied: you do not have permission to disarm this lock' });
  }

  const event = jsonEvent({
    type: 'DoorLockDisarmed',
    data: { lockId, disarmedBy: req.user.id, reason, disarmedAt: new Date() }
  });

  await esClient.appendToStream(`lock-${lockId}`, [event]);
  res.json({ success: true, lockId, state: 'DISARMED' });
});
